window.vaio2026Questions = [{"q":"Sắp xếp các bước theo đúng thứ tự của thuật toán EM khi huấn luyện Gaussian Mixture Model với K K thành phần: (1) M-step: cập nhật trọng số trộn π k π k ​ , trung bình μ k μ k ​ và hiệp phương sai Σ k Σ k ​ dựa trên các responsibility (2) Sau khi hội tụ, gán mỗi điểm vào thành phần có responsibility lớn nhất nếu cần phân cụm cứng (3) Khởi tạo tham số, ví dụ lấy tâm cụm của K-means làm các μ k μ k ​ ban đầu (4) Tính log-likelihood; nếu chưa hội tụ thì quay lại E-step (5) E-step: tính responsibility γ i k γ ik ​ , xác suất hậu nghiệm để điểm i i thuộc thành phần k k","code":"","a":["3 → → 1 → → 5 → → 4 → → 2","3 → → 5 → → 1 → → 4 → → 2","5 → → 3 → → 1 → → 4 → → 2","3 → → 5 → → 1 → → 2 → → 4"],"c":1,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":1},{"q":"Sắp xếp các bước theo đúng thứ tự huấn luyện và dự đoán của Random Forest cho bài toán phân loại: (1) Lặp lại quá trình trên cho đến khi đủ T T cây (2) Chọn phép tách tốt nhất (theo Gini hoặc entropy) trong các đặc trưng ứng viên và tiếp tục phát triển cây (3) Lấy mẫu bootstrap (có hoàn lại) từ tập huấn luyện cho cây hiện tại (4) Với mẫu mới, tổng hợp dự đoán của T T cây bằng bỏ phiếu đa số (5) Tại mỗi nút, chọn ngẫu nhiên một tập con gồm m m đặc trưng làm ứng viên","code":"","a":["5 → → 3 → → 2 → → 1 → → 4","3 → → 5 → → 2 → → 1 → → 4","3 → → 2 → → 5 → → 1 → → 4","3 → → 5 → → 2 → → 4 → → 1"],"c":1,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":2},{"q":"Sắp xếp các bước theo đúng thứ tự của thuật toán AC-3 để đảm bảo tính nhất quán cung (arc consistency) cho một CSP: (1) Khởi tạo hàng đợi chứa tất cả các cung (arc) ( X i , X j ) (X i ​ ,X j ​ ) tương ứng với mọi ràng buộc nhị phân trong bài toán (2) Nếu REVISE làm thay đổi d o m a i n ( X i ) domain(X i ​ ) (có giá trị bị loại), thêm lại vào hàng đợi tất cả các cung ( X k , X i ) (X k ​ ,X i ​ ) với X k X k ​ là láng giềng của X i X i ​ (khác X j X j ​ ) (3) Lặp lại cho đến khi hàng đợi rỗng (đạt trạng thái nhất quán cung) hoặc một domain rỗng (CSP vô nghiệm) (4) Thực hiện R E V I S E ( X i , X j ) REVISE(X i ​ ,X j ​ ): loại khỏi d o m a i n ( X i ) domain(X i ​ ) mọi giá trị không có giá trị tương ứng hợp lệ trong d o m a i n ( X j ) domain(X j ​ ) (5) Lấy ra một cung ( X i , X j ) (X i ​ ,X j ​ ) từ hàng đợi","code":"","a":["5 → → 1 → → 4 → → 2 → → 3","1 → → 4 → → 5 → → 2 → → 3","1 → → 5 → → 4 → → 2 → → 3","1 → → 5 → → 2 → → 4 → → 3"],"c":2,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":3},{"q":"Đoạn code chọn hành động theo epsilon-greedy nhưng có lỗi logic khiến agent explore khoảng 70% số bước thay vì khoảng 30% như mong muốn với epsilon=0.3. Lỗi nằm ở đâu?","code":"import random\r\ndef choose_action(Q_s, epsilon):\r\n    if random.random() > epsilon:\r\n        return random.choice(range(len(Q_s))) # explore\r\n    else:\r\n        return Q_s.index(max(Q_s)) # exploit","a":["Không có lỗi trong đoạn code này, nó đã cài đặt đúng chiến lược epsilon-greedy theo lý thuyết","Phải đổi hàm max(Q_s) thành min(Q_s) thì mới có thể tìm ra được hành động tốt nhất dựa theo bảng giá trị Q hiện tại","Hàm random.choice không tồn tại trong thư viện random chuẩn của Python","Điều kiện bị đảo ngược: random.random() > epsilon lại vào nhánh explore thay vì exploit; cần đổi thành < epsilon mới đúng là explore"],"c":3,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":4},{"q":"Đoạn code tính trọng số attention cho ma trận Q , K Q,K có shape ( n , d k ) (n,d k ​ ) (giả sử đã có hàm softmax theo hàng). Khi d k d k ​ lớn (ví dụ 64 thay vì 4), trọng số attention gần như one-hot (softmax bão hoà, gradient lan truyền ngược gần 0). Cần sửa thế nào?","code":"import numpy as np\r\ndef attention_score(Q, K):\r\n    scores = Q @ K.T # (n, n)\r\n    weights = softmax(scores)\r\n    return weights","a":["Đổi thành K@Q.T thay vì Q@K.T vì thứ tự nhân ma trận hiện tại trong đoạn code sai về mặt toán học","Không cần sửa vì hàm softmax phía sau đã tự chuẩn hoá tổng trọng số về 1, nên độ lớn của scores không ảnh hưởng","Sửa thành scores = Q @ K.T * d_k để nhân thêm hệ số d k d k ​ nhằm tăng cường độ lớn của điểm số attention","Sửa thành scores = (Q @ K.T) / np.sqrt(Q.shape[-1]) trước khi đưa vào softmax để tránh giá trị lớn làm softmax bão hoà (gradient nhỏ)"],"c":3,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":5},{"q":"Câu “Nếu trời mưa thì đường ướt” ( A → B A→B) tương đương logic với mệnh đề tuyển (disjunction) nào?","code":"","a":["A ∨ B A∨B","¬ A ∨ ¬ B ¬A∨¬B","A ∨ ¬ B A∨¬B","¬ A ∨ B ¬A∨B"],"c":3,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":6},{"q":"Hệ số tương quan hạng Spearman (Spearman’s rank correlation) phù hợp hơn Pearson trong trường hợp nào?","code":"","a":["Khi quan hệ giữa hai biến là tuyến tính, dữ liệu tuân theo phân phối chuẩn và không có outlier hay giá trị bất thường ảnh hưởng đến kết quả","Spearman và Pearson luôn cho kết quả giống nhau trên mọi tập dữ liệu, vì cả hai đều đo cùng một loại quan hệ tuyến tính giữa hai biến số","Khi quan hệ giữa hai biến là đơn điệu nhưng không nhất thiết tuyến tính, hoặc dữ liệu có outlier/không theo phân phối chuẩn — Spearman dựa trên thứ hạng nên bền vững hơn","Khi cả hai biến đều là dữ liệu phân loại không có thứ tự (nominal), vì lúc đó việc xếp hạng giá trị để tính rank correlation trở nên vô nghĩa"],"c":2,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":7},{"q":"Sắp xếp các bước theo đúng thứ tự khi fine-tune BERT cho bài toán phân loại văn bản: (1) Tách văn bản thành subword bằng tokenizer WordPiece của BERT (2) Lấy vector đầu ra tại [CLS] đưa qua lớp phân loại tuyến tính (3) Thêm token [CLS], [SEP], padding và tạo attention mask (4) Tính cross-entropy với nhãn và cập nhật tham số mô hình (5) Cho chuỗi đi qua các lớp encoder để có biểu diễn ngữ cảnh","code":"","a":["3 → → 1 → → 5 → → 2 → → 4","1 → → 5 → → 3 → → 2 → → 4","1 → → 3 → → 5 → → 2 → → 4","1 → → 3 → → 2 → → 5 → → 4"],"c":2,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":8},{"q":"Với kernel đa thức K ( x , z ) = ( x T z ) 2 , x = ( 1 , 2 ) , z = ( 3 , 1 ) K(x,z)=(x T z) 2 ,x=(1,2),z=(3,1). Giá trị K ( x , z ) K(x,z) và ý nghĩa của nó là:","code":"","a":["26, vì kernel đa thức luôn cộng thêm 1 vào tích vô hướng trước khi bình phương","5, bằng tích vô hướng của x x và z z trong không gian gốc; kernel chỉ đổi tên phép tính","25, bằng tích vô hướng ϕ ( x ) T ϕ ( z ) ϕ(x) T ϕ(z) trong không gian đặc trưng bậc hai, không cần tính ϕ ϕ tường minh","25, bằng bình phương khoảng cách Euclid giữa ϕ ( x ) ϕ(x) và ϕ ( z ) ϕ(z) trong không gian đặc trưng"],"c":2,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":9},{"q":"Trong ảnh nhị phân, foreground có giá trị 1. Phép dilation dùng phần tử cấu trúc vuông 3 × 3 3×3 toàn số 1, tâm ở giữa. Ảnh ban đầu chỉ có một pixel foreground nằm xa biên. Sau một lần dilation có bao nhiêu pixel foreground?","code":"","a":["1","3","8","9"],"c":3,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":10},{"q":"ViT chia ảnh 224 × 224 224×224 thành các patch 16 × 16 16×16 không chồng lấn, phủ kín ảnh, rồi thêm đúng một CLS token. Số token đầu vào Transformer là bao nhiêu?","code":"","a":["197","257","225","196"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":11},{"q":"Một lớp convolution thường có 16 kênh đầu vào, 32 kênh đầu ra, kernel 3 × 3 3×3 và một bias cho mỗi kênh đầu ra. Tổng số tham số học được của lớp là bao nhiêu?","code":"","a":["4608","4624","320","4640"],"c":3,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":12},{"q":"Trong suy diễn Logic vị từ bậc nhất (First-Order Logic), “Unification” (hợp nhất) được dùng để làm gì?","code":"","a":["Chuyển toàn bộ câu logic vị từ bậc nhất về dạng logic mệnh đề đơn giản hơn bằng cách loại bỏ mọi biến và lượng từ có mặt trong câu","Sắp xếp lại thứ tự xuất hiện của các lượng từ tồn tại ( ∃ ∃) và với mọi ( ∀ ∀) trong câu để đưa về dạng chuẩn tắc dễ đọc hơn","Tính xác suất một câu logic vị từ là hợp lệ dựa trên tần suất xuất hiện thống kê của các vị từ trong cơ sở tri thức đã cho","Tìm phép thế (substitution) cho các biến để hai literal trở nên trùng nhau về cú pháp, làm cơ sở áp dụng Resolution hay Modus Ponens tổng quát"],"c":3,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":13},{"q":"Trên một kho văn bản nhỏ có nhiều thuật ngữ y khoa hiếm, nhóm cần embedding tốt cho các từ hiếm. So sánh CBOW và Skip-gram, lựa chọn hợp lý là:","code":"","a":["CBOW, vì nó trung bình hóa ngữ cảnh nên vector của từ hiếm được cập nhật nhiều lần hơn","CBOW, vì nó dự đoán các từ ngữ cảnh từ từ tâm nên học tốt quan hệ của từ hiếm","Hai phương pháp tương đương; khác biệt duy nhất nằm ở tốc độ huấn luyện","Skip-gram, vì mỗi lần từ hiếm xuất hiện nó tạo nhiều cặp huấn luyện nên vector của nó được cập nhật nhiều lần hơn"],"c":3,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":14},{"q":"Sắp xếp các bước theo đúng thứ tự trong một vòng huấn luyện mô hình ngôn ngữ RNN bằng truncated BPTT trên một đoạn dài L L token: (1) Cắt (clip) norm của gradient nếu vượt ngưỡng (2) Lan truyền ngược qua L L bước thời gian của đoạn (3) Chạy RNN tuần tự qua L L token, tính các trạng thái ẩn h t h t ​ (4) Tính cross-entropy tại mỗi bước giữa dự đoán và token kế tiếp (5) Cập nhật tham số, rồi giữ h L h L ​ (đã detach) làm trạng thái đầu cho đoạn tiếp theo","code":"","a":["3 → → 4 → → 2 → → 1 → → 5","3 → → 2 → → 4 → → 1 → → 5","3 → → 4 → → 1 → → 2 → → 5","4 → → 3 → → 2 → → 1 → → 5"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":15},{"q":"Xét hai tình huống: (1) cây quyết định sâu, lỗi huấn luyện gần 0 nhưng lỗi kiểm định cao và dao động giữa các lần chia dữ liệu; (2) cây quyết định độ sâu 1 (stump), lỗi huấn luyện và lỗi kiểm định đều cao. Phương pháp ensemble phù hợp lần lượt là:","code":"","a":["(1) Boosting để giảm bias; (2) Bagging để giảm variance","(1) Bagging hoặc Random Forest để giảm variance; (2) Boosting để giảm bias","Cả hai dùng Bagging, vì bagging giảm đồng thời cả bias và variance","Cả hai dùng Boosting, vì boosting luôn tốt hơn bagging với cây quyết định"],"c":1,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":16},{"q":"Cho 7 điểm ( x , y ) (x,y) với x = − 3 , − 2 , − 1 , 0 , 1 , 2 , 3 x=−3,−2,−1,0,1,2,3 và y = x 3 y=x 3 . Phát biểu nào đúng về hệ số tương quan Pearson ( r r) và Spearman ( ρ ρ) giữa x x và y y?","code":"","a":["r = 1 r=1 vì y y là một hàm xác định của x x, còn ρ < 1 ρ<1","Cả r r và ρ ρ đều bằng 0 vì hàm y = x 3 y=x 3 đối xứng qua gốc tọa độ","ρ = 1 ρ=1 còn r < 1 r<1, vì quan hệ đơn điệu tăng nhưng không tuyến tính","r = 1 r=1 còn ρ < 1 ρ<1, vì các giá trị lớn như 27 làm méo thứ hạng"],"c":2,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":17},{"q":"Một kho gồm N = 1000 N=1000 văn bản. Văn bản d d dài 100 từ. Từ “transformer” xuất hiện 4 lần trong d d và có mặt trong 10 văn bản của kho. Từ “là” xuất hiện 10 lần trong d d và có mặt trong cả 1000 văn bản. Với T F = s o ˆ ˊ l a ˆ ˋ n xu a ˆ ˊ t hiện / độ d a ˋ i v a ˘ n bản TF=s o ˆ ˊ l a ˆ ˋ n xu a ˆ ˊ t hiện/độ d a ˋ i v a ˘ n bản và I D F = log ⁡ 10 ( N / d f ) IDF=log 10 ​ (N/df), TF-IDF của “transformer” và “là” trong d d lần lượt là:","code":"","a":["0.04 và 0.10","8 và 0","0.08 và 0.10","0.08 và 0"],"c":3,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":18},{"q":"Đoạn code kiểm tra tính thoả mãn được (satisfiability) của công thức CNF bằng cách thử toàn bộ 2 n 2 n phép gán chân trị (brute-force). Đoạn code có lỗi khiến nó báo sai “UNSAT” (không thoả mãn) cho nhiều công thức thực ra thoả mãn được, ví dụ clauses = [[1, 2], [-1, -2]] (thoả mãn với x1=True, x2=False). Lỗi nằm ở đâu?","code":"from itertools import product\ndef is_satisfiable(clauses, variables):\r\n    for values in product([True, False], repeat=len(variables)):\r\n        assignment = dict(zip(variables, values))\r\n        satisfied = True\r\n        for clause in clauses:\r\n            clause_value = all(\r\n                assignment[abs(lit)] if lit > 0 else not assignment[abs(lit)]\r\n                for lit in clause\r\n            )\r\n            if not clause_value:\r\n                satisfied = False\r\n        if satisfied:\r\n            return True, assignment\r\n    return False, None","a":["Một clause chỉ cần MỘT literal đúng là đủ thoả mãn; code đang dùng all(...) (yêu cầu mọi literal đúng) thay vì any(...), làm sai ngữ nghĩa OR trong mỗi clause","Lỗi nằm ở việc dùng itertools.product để sinh tổ hợp chân trị; cần thay bằng vòng lặp for lồng nhau theo từng biến vì product không duyệt hết mọi tổ hợp 2 n 2 n giá trị True/False","Lỗi nằm ở dict(zip(variables, values)); cần dùng list thay vì dict để ánh xạ biến sang giá trị, vì dict không giữ đúng thứ tự khi tra cứu assignment[abs(lit)]","Không có lỗi, code đã đúng vì itertools.product đã duyệt đủ 2 n 2 n phép gán và điều kiện if not clause_value đã loại đúng các phép gán không thoả mãn công thức"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":19},{"q":"Cho V ( s ′ ) = 10 V(s ′ )=10, phần thưởng tức thời r = 5 r=5, hệ số chiết khấu γ = 0.9 γ=0.9. Theo phương trình Bellman cho giá trị trạng thái (deterministic, 1 hành động), V ( s ) = r + γ V ( s ′ ) V(s)=r+γV(s ′ ) bằng bao nhiêu?","code":"","a":["5.9","14.0","15.0","9.0"],"c":1,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":20},{"q":"Sắp xếp các bước theo đúng thứ tự của một vòng lặp huấn luyện dùng SGD với Momentum, cập nhật cho MỖI tham số: (1) Tính gradient g t = ∇ L ( θ t − 1 ) g t ​ =∇L(θ t−1 ​ ) của hàm mất mát tại tham số hiện tại (2) Cập nhật tham số theo hướng vận tốc: θ t = θ t − 1 − η v t θ t ​ =θ t−1 ​ −ηv t ​ (3) Lặp lại cho batch tiếp theo, dùng v t v t ​ vừa tính làm vận tốc cũ ( v t − 1 v t−1 ​ ) ở bước sau (4) Cập nhật vận tốc: v t = β v t − 1 + ( 1 − β ) g t v t ​ =βv t−1 ​ +(1−β)g t ​ (hoặc v t = β v t − 1 + g t v t ​ =βv t−1 ​ +g t ​ tuỳ biến thể)","code":"","a":["1 → → 2 → → 4 → → 3","4 → → 1 → → 2 → → 3","1 → → 4 → → 3 → → 2","1 → → 4 → → 2 → → 3"],"c":3,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":21},{"q":"Sắp xếp các bước theo đúng thứ tự của một vòng lặp Gradient Descent khi huấn luyện hồi quy tuyến tính: (1) Cập nhật tham số: w ← w − η ∇ w L , b ← b − η ∂ L / ∂ b w←w−η∇ w ​ L,b←b−η∂L/∂b (2) Tính giá trị dự đoán y ^ = X w + b y ^ ​ =Xw+b cho toàn bộ (hoặc một batch) dữ liệu (3) Tính gradient của hàm mất mát theo w w và b b: ∇ w L , ∂ L / ∂ b ∇ w ​ L,∂L/∂b (4) Khởi tạo trọng số w w và bias b b (thường ngẫu nhiên hoặc bằng 0) (5) Tính hàm mất mát L L (ví dụ MSE) giữa y ^ y ^ ​ và nhãn thật y y","code":"","a":["4 → → 2 → → 5 → → 3 → → 1","2 → → 4 → → 5 → → 3 → → 1","4 → → 5 → → 2 → → 3 → → 1","4 → → 2 → → 5 → → 1 → → 3"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":22},{"q":"Đoạn code huấn luyện hồi quy Ridge (L2 regularization) với sklearn. Khi tăng alpha từ 0.1 lên 100, các hệ số hồi quy (coef_) thay đổi theo xu hướng nào, và tại sao?","code":"from sklearn.linear_model import Ridge\nmodel_low = Ridge(alpha=0.1).fit(X_train, y_train)\r\nmodel_high = Ridge(alpha=100).fit(X_train, y_train)\r\nprint(model_low.coef_)\r\nprint(model_high.coef_)","a":["Các hệ số của model_high nhìn chung bị co về gần 0 hơn (chuẩn ∥ w ∥ 2 ∥w∥ 2 ​ nhỏ hơn) so với model_low, vì alpha lớn phạt nặng hơn tổng bình phương hệ số, ép mô hình đơn giản hơn nhưng có thể tăng bias","Các hệ số của model_high sẽ lớn hơn so với model_low, vì alpha lớn khuyến khích mô hình khớp sát hơn với từng điểm dữ liệu huấn luyện","Không có sự khác biệt vì alpha không ảnh hưởng đến coef_, chỉ ảnh hưởng đến sai số dự đoán trên tập kiểm tra","alpha chỉ ảnh hưởng đến tốc độ hội tụ của thuật toán tối ưu, không ảnh hưởng gì đến giá trị coef_ cuối cùng sau khi hội tụ"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":23},{"q":"Đoạn code sau tính Precision và Recall từ ma trận nhầm lẫn nhị phân. Với TP = 15, FP = 5, FN = 10, TN = 70, kết quả in ra là gì (làm tròn 2 chữ số)?","code":"TP, FP, FN, TN = 15, 5, 10, 70\r\nprecision = TP / (TP + FP)\r\nrecall = TP / (TP + FN)\r\nprint(round(precision, 2), round(recall, 2))","a":["0.75 0.67","0.75 0.6","0.6 0.75","0.15 0.1"],"c":1,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":24},{"q":"","code":"import numpy as np\ny = np.array([3.0, 5.0, 10.0])\nF = np.full_like(y, y.mean()) # mô hình khởi tạo F0\nlr = 0.5\nfor m in range(2):\nr = y - F # phần dư = gradient âm của MSE/2\nh = r # giả sử cây hồi quy khớp đúng phần dư\nF = F + lr * h\nprint(F.tolist())\nKết quả in ra là:","a":["[3.0, 5.0, 10.0]","[4.5, 5.5, 8.0]","[3.75, 5.25, 9.0]","[6.0, 6.0, 6.0]"],"c":2,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":25},{"q":"Một ảnh có đúng một đối tượng ground truth. Có hai detection đúng lớp, score 0.9 và 0.8; mỗi detection đều có IoU = 0.8 với đối tượng đó. Đánh giá xét score giảm dần, ghép một đối một, ngưỡng IoU ≥ 0.5 ≥0.5; không có ground truth bị bỏ qua. Cặp (TP, FP) là gì?","code":"","a":["(1,1)","(1,0)","(2,0)","(0,2)"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":26},{"q":"Hàm mất mát (cost function) phổ biến nhất dùng để huấn luyện hồi quy logistic là gì, và vì sao không dùng MSE như hồi quy tuyến tính?","code":"","a":["Hinge loss, vì hồi quy logistic về bản chất cũng tối đa hoá lề phân cách giống như SVM tuyến tính","Mean Absolute Error, vì nó ít nhạy cảm với các điểm ngoại lai hơn so với các hàm mất mát bình phương","MSE, vì công thức đơn giản dễ tính và luôn là hàm lồi (convex) khi kết hợp với sigmoid","Binary cross-entropy (log-loss), vì MSE kết hợp sigmoid tạo ra hàm mất mát không lồi, dễ kẹt cực tiểu địa phương"],"c":3,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":27},{"q":"Một mô hình có Precision = 0.8 và Recall = 0.4. F1-score xấp xỉ bao nhiêu?","code":"","a":["0.44","0.53","0.60","0.32"],"c":1,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":28},{"q":"Một mạng chứa Dropout và BatchNorm. Trong cơ chế tự động tính gradient thông thường, chỉ tắt ghi nhận gradient, nhưng vẫn để mô hình ở training mode. Điều nào đúng?","code":"","a":["Dropout tự tắt ngay khi tắt gradient","Dropout vẫn có thể ngẫu nhiên và BatchNorm vẫn có thể cập nhật thống kê","BatchNorm tự chuyển sang dùng running statistics như evaluation mode","Tắt gradient luôn tương đương chuyển sang evaluation mode"],"c":1,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":29},{"q":"Trong hồi quy logistic, biên quyết định (decision boundary) ứng với ngưỡng xác suất 0.5 tương ứng với điều kiện nào trên tổ hợp tuyến tính z = w ⋅ x + b z=w⋅x+b?","code":"","a":["z = − 1 z=−1","z = 1 z=1","z = 0.5 z=0.5","z = 0 z=0"],"c":3,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":30},{"q":"Vì sao một Perceptron đơn tầng (single-layer) không thể học được hàm XOR?","code":"","a":["Vì XOR đòi hỏi một hàm mất mát khác với MSE mà một perceptron đơn tầng không có khả năng tính đạo hàm được","Vì XOR không phải là bài toán phân tách tuyến tính (linearly separable), trong khi perceptron đơn tầng chỉ tạo được 1 siêu phẳng phân tách tuyến tính","Vì hàm XOR không phải là một hàm boolean hợp lệ theo định nghĩa của logic mệnh đề nhị phân chuẩn","Vì Perceptron đơn tầng chỉ có khả năng nhận đầu vào là số thực liên tục, không nhận được đầu vào nhị phân 0/1"],"c":1,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":31},{"q":"Sắp xếp các bước theo đúng thứ tự của thuật toán Minimax với cắt tỉa Alpha-Beta khi duyệt cây trò chơi từ gốc (lượt Max): (1) Khi đến nút lá (hoặc giới hạn độ sâu), trả về giá trị hàm đánh giá (2) Đệ quy xuống các nút con, đổi vai trò Max/Min ở mỗi tầng (3) Khi một nút con trả về giá trị: cập nhật giá trị tốt nhất của nút hiện tại cùng α α (nút Max) hoặc β β (nút Min); nếu điều kiện cắt tỉa được thoả mãn thì bỏ qua các nút con còn lại (4) Chọn nước đi tại gốc ứng với nút con cho giá trị tốt nhất (5) Khởi tạo α = − ∞ , β = + ∞ α=−∞,β=+∞ tại nút gốc","code":"","a":["5 → → 1 → → 2 → → 3 → → 4","2 → → 5 → → 1 → → 3 → → 4","5 → → 2 → → 3 → → 1 → → 4","5 → → 2 → → 1 → → 3 → → 4"],"c":3,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":32},{"q":"Đoạn code huấn luyện PyTorch dưới đây chạy không báo lỗi, nhưng quá trình huấn luyện không ổn định: loss dao động, có lúc tăng vọt, dù learning rate đã được chọn hợp lý. Lỗi nằm ở đâu?","code":"for epoch in range(num_epochs):\r\n    for x_batch, y_batch in dataloader:\r\n        output = model(x_batch)\r\n        loss = criterion(output, y_batch)\r\n        loss.backward()\r\n        optimizer.step()\r\nprint(\"done\")","a":["Thiếu lệnh model.eval() trước vòng lặp huấn luyện khiến Batch Normalization và Dropout hoạt động sai chế độ trong lúc train","DataLoader không được phép sử dụng bên trong vòng lặp for khi huấn luyện, phải nạp toàn bộ dữ liệu vào một tensor trước","Thiếu optimizer.zero_grad() trong mỗi vòng lặp (trước loss.backward()), khiến gradient cộng dồn qua các batch.","Thiếu lệnh criterion.backward() thay vì gọi loss.backward(), khiến đồ thị tính toán gradient không được xây dựng đúng cách"],"c":2,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":33},{"q":"Sắp xếp các bước theo đúng thứ tự của phương pháp Monte Carlo để ước lượng hàm giá trị V ( s ) V(s) theo một chính sách π π cố định: (1) Cho agent chạy theo chính sách π π để sinh ra một episode đầy đủ (từ trạng thái đầu đến trạng thái kết thúc) (2) Với mỗi trạng thái xuất hiện trong episode, tính tổng phần thưởng chiết khấu (return) G t G t ​ kể từ thời điểm đó đến hết episode (3) Ước lượng V ( s ) V(s) bằng trung bình cộng của tất cả các return đã quan sát được cho trạng thái s s (4) Cộng dồn các giá trị return G t G t ​ quan sát được cho từng trạng thái qua nhiều episode","code":"","a":["2 → → 1 → → 4 → → 3","1 → → 4 → → 2 → → 3","1 → → 3 → → 2 → → 4","1 → → 2 → → 4 → → 3"],"c":3,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":34},{"q":"“Support vector” trong SVM là những điểm dữ liệu nào?","code":"","a":["Các điểm bị phân loại sai trong quá trình huấn luyện và do đó bị loại bỏ khỏi tập dữ liệu để không ảnh hưởng đến siêu phẳng","Mọi điểm trong tập huấn luyện, không phân biệt vị trí gần hay xa siêu phẳng, đều đóng góp như nhau vào việc xác định nghiệm cuối cùng","Các điểm nằm gần siêu phẳng phân tách nhất, nằm đúng trên đường biên lề (margin) hoặc vi phạm lề — chính các điểm này quyết định vị trí/hướng của siêu phẳng","Các điểm nằm xa siêu phẳng phân tách nhất, vì chúng thể hiện rõ nhất đặc trưng điển hình của lớp mà chúng thuộc về"],"c":2,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":35},{"q":"Sắp xếp các bước theo đúng thứ tự để tính hệ số tương quan Pearson r r giữa hai biến X , Y X,Y từ dữ liệu thô: (1) Tính trung bình cộng của X X ( x ˉ x ˉ ) và của Y Y ( y ˉ y ˉ ​ ) (2) Tính r = S x y / S x x S y y r=S xy ​ / S xx ​ S yy ​ ​ (3) Tính các tổng: S x y = ∑ ( x i − x ˉ ) ( y i − y ˉ ) , S x x = ∑ ( x i − x ˉ ) 2 , S y y = ∑ ( y i − y ˉ ) 2 S xy ​ =∑(x i ​ − x ˉ )(y i ​ − y ˉ ​ ),S xx ​ =∑(x i ​ − x ˉ ) 2 ,S yy ​ =∑(y i ​ − y ˉ ​ ) 2 (4) Tính mẫu số S x x S y y S xx ​ S yy ​ ​ từ các tổng bình phương độ lệch ở bước trước (5) Tính độ lệch của từng điểm so với trung bình: ( x i − x ˉ ) (x i ​ − x ˉ ) và ( y i − y ˉ ) (y i ​ − y ˉ ​ )","code":"","a":["1 → → 5 → → 3 → → 4 → → 2","5 → → 1 → → 3 → → 4 → → 2","1 → → 3 → → 5 → → 4 → → 2","1 → → 5 → → 3 → → 2 → → 4"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":36},{"q":"Sắp xếp các bước theo đúng thứ tự của phân cụm phân cấp kiểu gộp dần (agglomerative hierarchical clustering): (1) Lặp lại việc gộp cụm cho đến khi chỉ còn 1 cụm hoặc đạt số cụm mong muốn (2) Tính ma trận khoảng cách giữa mọi cặp cụm hiện có (3) Gộp hai cụm gần nhau nhất (theo tiêu chí linkage đã chọn) thành một cụm mới (4) Cập nhật lại ma trận khoảng cách với cụm mới vừa tạo (5) Khởi tạo mỗi điểm dữ liệu là một cụm riêng biệt","code":"","a":["5 → → 2 → → 3 → → 4 → → 1","2 → → 5 → → 3 → → 4 → → 1","5 → → 3 → → 2 → → 4 → → 1","5 → → 2 → → 4 → → 3 → → 1"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":37},{"q":"Dữ liệu đã được trừ trung bình. Đặc trưng x 1 x 1 ​ độc lập với nhãn, có phương sai 100. Đặc trưng x 2 x 2 ​ chỉ nhận − 1 −1 ở lớp A và + 1 +1 ở lớp B; hai lớp cân bằng. Hiệp phương sai giữa x 1 x 1 ​ và x 2 x 2 ​ bằng 0. Áp dụng PCA (Phân tích thành phần chính) trên ma trận hiệp phương sai, không chuẩn hóa phương sai và chỉ giữ một thành phần chính. Điều gì xảy ra?","code":"","a":["Giữ trục x 1 x 1 ​ và chuyển thông tin nhãn của x 2 x 2 ​ sang trục đó.","Giữ trục x 1 x 1 ​ và làm mất thông tin phân biệt lớp từ x 2 x 2 ​ .","Giữ hai trục với trọng số bằng nhau trong thành phần mới.","Giữ trục x 2 x 2 ​ và bảo toàn thông tin phân biệt hai lớp."],"c":1,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":38},{"q":"Một nút của cây quyết định chứa 8 mẫu: 4 dương, 4 âm. Phép tách theo thuộc tính A tạo nút trái gồm 4 mẫu (3 dương, 1 âm) và nút phải gồm 4 mẫu (1 dương, 3 âm). Information Gain (theo entropy, cơ số 2) của phép tách xấp xỉ bằng bao nhiêu? Cho log ⁡ 2 3 ≈ 1.585 log 2 ​ 3≈1.585.","code":"","a":["0.811","0.125","0.189","1.000"],"c":2,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":39},{"q":"Nguyên nhân chính gây ra hiện tượng “vanishing gradient” khi huấn luyện mạng nơ-ron sâu dùng hàm kích hoạt sigmoid hoặc tanh ở mọi tầng là gì?","code":"","a":["Dữ liệu đầu vào chưa được thực hiện bước one-hot encode một cách đầy đủ trước khi đưa vào huấn luyện toàn bộ mạng","Đạo hàm của sigmoid hoặc tanh luôn ≤ 1 ≤1 và gần 0 ở vùng bão hoà; qua nhiều tầng, tích các đạo hàm này (chain rule) co lại về 0 theo hàm mũ","Số lượng tham số của toàn bộ mạng không đủ so với độ phức tạp của tập dữ liệu đang xét","Giá trị learning rate đang được đặt lớn hơn mức cần thiết để hội tụ ổn định"],"c":1,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":40},{"q":"Bốn mẫu có điểm dự đoán như sau: hai mẫu dương có điểm 0.9 và 0.6; hai mẫu âm có điểm 0.7 và 0.2. ROC-AUC bằng bao nhiêu?","code":"","a":["0.50","0.67","0.75","1.00"],"c":2,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":41},{"q":"So với K-means, Gaussian Mixture Model (GMM) khác biệt cơ bản ở điểm nào?","code":"","a":["GMM gán cứng (hard assignment) mỗi điểm dữ liệu vào đúng một cụm, còn K-means lại gán mềm (soft) theo xác suất thành viên","Cả hai đều là thuật toán học có giám sát (supervised), cần có nhãn lớp được gán sẵn từ trước để tiến hành huấn luyện mô hình phân cụm","GMM gán mềm (soft assignment) — mỗi điểm có xác suất thuộc về từng cụm (component Gauss), ước lượng bằng thuật toán EM; K-means gán cứng dựa trên khoảng cách gần nhất","GMM chỉ hoạt động được với dữ liệu một chiều (1-D) và không mở rộng được lên không gian đặc trưng nhiều chiều"],"c":2,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":42},{"q":"Sắp xếp các bước theo đúng thứ tự của tìm kiếm theo chiều sâu (Depth-First Search - DFS) dùng đệ quy/ngăn xếp trên một đồ thị: (1) Nếu nút đó là đích, trả về đường đi đã tìm được (2) Lấy nút ở đỉnh ngăn xếp ra để xét, đánh dấu đã thăm (3) Đẩy các nút lân cận chưa thăm của nút hiện tại vào ngăn xếp (4) Lặp lại việc lấy đỉnh ngăn xếp cho đến khi tìm thấy đích hoặc ngăn xếp rỗng (5) Khởi tạo ngăn xếp (stack) chỉ chứa nút bắt đầu","code":"","a":["5 → → 2 → → 1 → → 3 → → 4","2 → → 5 → → 1 → → 3 → → 4","5 → → 1 → → 2 → → 3 → → 4","5 → → 2 → → 1 → → 4 → → 3"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":43},{"q":"Đoạn code tính Cross-Entropy loss thủ công cho 1 mẫu phân loại 3 lớp với nhãn thật là lớp 1 (index bắt đầu từ 0) và xác suất dự đoán y_pred = [0.2, 0.5, 0.3]. Giá trị loss in ra (làm tròn 3 chữ số) là bao nhiêu?","code":"import numpy as np\r\ny_pred = np.array([0.2, 0.5, 0.3])\r\ntrue_class = 1\r\nloss = -np.log(y_pred[true_class])\r\nprint(round(loss, 3))","a":["1.609","0.693","0.357","0.511"],"c":1,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":44},{"q":"Đoạn code cài đặt BFS trên đồ thị không trọng số biểu diễn bằng dict kề. Giá trị in ra là bao nhiêu?","code":"from collections import deque\ndef bfs(graph, start, goal):\r\n    queue = deque([[start]])\r\n    visited = {start}\r\n    while queue:\r\n        path = queue.popleft()\r\n        node = path[-1]\r\n        if node == goal:\r\n            return path\r\n        for nxt in graph[node]:\r\n            if nxt not in visited:\r\n                visited.add(nxt)\r\n                queue.append(path + [nxt])\r\n    return None\nresult = bfs({'A':['B','C'],'B':['D'],'C':['D'],'D':[]}, 'A', 'D')\r\nprint(len(result))","a":["1","2","3","4"],"c":2,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":45},{"q":"Một mạng chỉ gồm ba lớp tuyến tính liên tiếp, mỗi lớp có thể có bias, không có activation hay phép toán nào khác. Xét hàm từ đầu vào tới đầu ra, mạng này tương đương với gì?","code":"","a":["Một phép biến đổi affine duy nhất","Một convolution có kernel cố định","Một hàm phi tuyến do có nhiều lớp","Một cây quyết định có ba tầng"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":46},{"q":"Sắp xếp các bước theo đúng thứ tự của phương pháp chứng minh bằng phản chứng dùng Resolution (Proof by Refutation) để kiểm tra xem một tập tiên đề KB có suy ra được câu α α hay không: (1) Nếu không có clause rỗng và vòng lặp không sinh thêm được clause mới nào (bão hoà) thì dừng, kết luận KB không suy ra được α α; ngược lại quay lại bước lặp (2) Sau mỗi vòng lặp, kiểm tra trước tiên: nếu trong các clause vừa sinh có clause rỗng ( ∅ ∅) thì dừng, kết luận KB ⊨ α ⊨α (3) Phủ định câu cần chứng minh: thêm ¬ α ¬α vào tập tiên đề KB (4) Lặp lại: chọn hai clause có literal đối lập, áp dụng luật Resolution để sinh clause mới, thêm vào tập clause (5) Chuyển toàn bộ K B ∪ { ¬ α } KB∪{¬α} về dạng chuẩn tắc hội (CNF), biểu diễn thành tập các clause","code":"","a":["3 → → 5 → → 4 → → 2 → → 1","5 → → 3 → → 4 → → 2 → → 1","3 → → 4 → → 5 → → 2 → → 1","3 → → 5 → → 4 → → 1 → → 2"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":47},{"q":"Huấn luyện SVM soft-margin trên dữ liệu có một số điểm nhiễu nằm lẫn sang vùng của lớp kia. Nếu tăng C C từ 1 lên 1 0 4 10 4 , điều gì nhiều khả năng xảy ra?","code":"","a":["Margin rộng hơn vì mô hình được phép bỏ qua nhiều điểm vi phạm hơn","Kernel tự chuyển từ tuyến tính sang RBF để tách được các điểm nhiễu","Vi phạm margin bị phạt nặng hơn nên margin hẹp lại, mô hình cố khớp cả điểm nhiễu và dễ overfit","Số support vector tăng vì mọi điểm đều buộc phải nằm đúng trên biên của margin"],"c":2,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":48},{"q":"Trong sàng lọc ảnh lỗi sản phẩm, yêu cầu ưu tiên là bỏ sót càng ít ảnh lỗi càng tốt. Các cảnh báo nhầm sẽ được nhân viên kiểm tra lại. Metric nào trực tiếp đo tỷ lệ ảnh lỗi thật được phát hiện?","code":"","a":["Accuracy toàn bộ tập","Precision của lớp bình thường","Recall của lớp lỗi","Precision của lớp lỗi"],"c":2,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":49},{"q":"Ảnh rộng 640, cao 480 được thu nhỏ đồng đều để vừa khung 320 × 320 320×320 mà không méo ảnh, rồi thêm viền trên và dưới bằng nhau. Điểm ( x , y ) = ( 200 , 100 ) (x,y)=(200,100) trong hệ tọa độ liên tục của ảnh gốc chuyển thành điểm nào? Gốc tọa độ ở góc trên trái; bỏ qua quy ước tâm pixel.","code":"","a":["(200, 140)","(100, 90)","(140, 50)","(100, 50)"],"c":1,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":50},{"q":"Đoạn code tính độ tương đồng cosine giữa embedding trung bình của 2 câu (mean pooling word vectors) nhưng lỗi khi 1 câu chứa từ không có trong từ điển embedding (out-of-vocabulary). Cách sửa hợp lý nhất?","code":"def sentence_vector(tokens, embeddings, dim=100):\r\n    vecs = [embeddings[t] for t in tokens]\r\n    return np.mean(vecs, axis=0)","a":["Phải dừng chương trình ngay khi gặp từ lạ và báo lỗi cho người dùng, vì không có cách nào xử lý được từ ngoài từ điển embedding đã huấn luyện","Không cần sửa, mọi từ trong tập dữ liệu thực tế luôn có sẵn trong bộ từ điển embeddings đã huấn luyện trước nên KeyError sẽ không bao giờ xảy ra","Cần bỏ qua (hoặc thay bằng vector 0) các từ không có trong embeddings, ví dụ dùng embeddings.get(t, np.zeros(dim)), tránh KeyError","Phải xoá toàn bộ câu chứa từ lạ đó khỏi tập dữ liệu trước khi huấn luyện, chấp nhận mất một phần dữ liệu để tránh lỗi khi tra cứu embedding"],"c":2,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":51},{"q":"","code":"import torch.nn.functional as F\nlogits = model(input_ids).logits # (B, T, V), có causal mask\r\nloss = F.cross_entropy(\r\n    logits.view(-1, logits.size(-1)), # (B*T, V)\r\n    input_ids.view(-1) # (B*T,)\r\n)\r\nloss.backward()\nKhi huấn luyện một mô hình causal LM bằng đoạn code trên, loss giảm nhanh về gần 0 nhưng mô hình sinh văn bản vô nghĩa. Lỗi và cách sửa là gì?","a":["Gọi .view trên tensor không liên tục bộ nhớ; cần đổi sang .reshape","Nhãn chưa được dịch: vị trí t t học dự đoán chính token t t; cần so logits[:, :-1] với input_ids[:, 1:]","Thiếu softmax: cần áp softmax lên logits trước khi đưa vào cross_entropy","Causal mask che mất ngữ cảnh cần thiết; cần attention hai chiều như BERT để thấy token tương lai"],"c":1,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":52},{"q":"Trong DBSCAN, một điểm được gọi là “điểm nhiễu” (noise) khi nào?","code":"","a":["Khi nó là một điểm lõi (core point) nhưng lại nằm ở vị trí biên ngoài cùng của cụm được hình thành","Khi nó có giá trị một đặc trưng nào đó là ngoại lai (outlier) tính theo chỉ số z-score vượt ngưỡng 3","Khi khoảng cách từ nó đến tâm cụm gần nhất lớn hơn một nửa bán kính eps đã chọn trước","Khi số điểm lân cận trong bán kính eps nhỏ hơn MinPts và nó không nằm trong vùng lân cận của bất kỳ điểm lõi nào"],"c":3,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":53},{"q":"Đoạn code cài đặt A* dùng heapq nhưng đôi khi trả về đường đi KHÔNG tối ưu dù heuristic là admissible. Nguyên nhân nhiều khả năng nhất trong đoạn code là gì?","code":"import heapq\ndef a_star(start, goal, neighbors_fn, h):\r\n    open_heap = [(h(start), 0, start, [start])]\r\n    visited = set()\r\n    while open_heap:\r\n        f, g, node, path = heapq.heappop(open_heap)\r\n        if node in visited:\r\n            continue\r\n        visited.add(node)\r\n        if node == goal:\r\n            return path, g\r\n        for nxt, cost in neighbors_fn(node):\r\n            new_g = g + cost\r\n            heapq.heappush(open_heap, (new_g + h(nxt), new_g, nxt, path + [nxt]))\r\n    return None","a":["heapq trong Python không hỗ trợ so sánh tuple có 4 phần tử khi hai phần tử đầu bằng nhau, nên sẽ ném ra lỗi TypeError ngay khi chạy","Tập visited đóng vĩnh viễn một node ngay lần đầu lấy ra và không cho mở lại (reopen) khi sau đó tìm được g nhỏ hơn; với heuristic chỉ admissible mà không consistent, điều này chặn nhầm đường tốt hơn xuất hiện sau","Code này đúng, đây là một cài đặt A* hợp lệ theo sách giáo khoa và không có lỗi tối ưu nào cần sửa","Phải thay cấu trúc heapq bằng một list thường và tự sắp xếp lại sau mỗi lần thêm phần tử để đảm bảo thuật toán tối ưu"],"c":1,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":54},{"q":"Sắp xếp các bước theo đúng thứ tự của MỘT vòng lặp huấn luyện GAN (Generative Adversarial Network): (1) Tính loss của G (đánh lừa D hiệu quả hơn) và cập nhật trọng số G, giữ D cố định (2) Generator G sinh ảnh giả G(z) từ z (3) Discriminator D chấm điểm cả ảnh thật và ảnh giả G(z) (4) Lấy mẫu vector nhiễu ngẫu nhiên z từ phân phối tiên nghiệm (ví dụ Gaussian) (5) Tính loss của D (phân biệt thật/giả tốt hơn) và cập nhật trọng số D","code":"","a":["4 → → 2 → → 3 → → 5 → → 1","2 → → 4 → → 3 → → 5 → → 1","4 → → 3 → → 2 → → 5 → → 1","4 → → 2 → → 5 → → 3 → → 1"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":55},{"q":"Đoạn code PyTorch định nghĩa Conv2d với input ảnh (batch=1, channel=3, 32 × 32 32×32), kernel 3 × 3 3×3, stride=1, padding=1. out.shape in ra là gì?","code":"import torch\r\nimport torch.nn as nn\nconv = nn.Conv2d(in_channels=3, out_channels=16, kernel_size=3, stride=1, padding=1)\r\nx = torch.randn(1, 3, 32, 32)\r\nout = conv(x)\r\nprint(out.shape)","a":["torch.Size([1, 3, 32, 32])","torch.Size([16, 1, 32, 32])","torch.Size([1, 16, 32, 32])","torch.Size([1, 16, 30, 30])"],"c":2,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":56},{"q":"Xét một nút của cây quyết định trong bài toán phân loại nhị phân (hai lớp: lớp 1 và lớp 0). Gọi p p là tỉ lệ mẫu thuộc lớp 1 trong nút ( 0 ≤ p ≤ 1 0≤p≤1); khi đó tỉ lệ mẫu thuộc lớp 0 là 1 − p 1−p. Gini impurity của nút là G i n i = 1 − ∑ i p i 2 Gini=1−∑ i ​ p i 2 ​ , trong đó p i p i ​ là tỉ lệ mẫu thuộc lớp i i trong nút và tổng lấy trên tất cả các lớp. Hàm gini(p) dưới đây nhận p p và trả về Gini impurity của nút, nhưng có lỗi. Lỗi ở đâu và sửa thế nào?","code":"def gini(p):\r\n    return 1 - (p**2 + (1 - p))","a":["Sai: phải là 1 + ( p ∗ ∗ 2 + ( 1 − p ) ∗ ∗ 2 ) 1+(p∗∗2+(1−p)∗∗2) cộng thêm hằng số hiệu chỉnh vào công thức gốc","Sai: phải là p ∗ ∗ 2 − ( 1 − p ) ∗ ∗ 2 p∗∗2−(1−p)∗∗2 lấy hiệu hai bình phương xác suất từng lớp","Sai: phải là 1 − ( p ∗ ∗ 2 + ( 1 − p ) ∗ ∗ 2 ) 1−(p∗∗2+(1−p)∗∗2) (bình phương cả xác suất lớp còn lại)","Đúng công thức rồi, không cần sửa gì thêm trong đoạn code hiện tại"],"c":2,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":57},{"q":"Dữ liệu 2D gồm hai vành tròn đồng tâm. K-means với K = 2 K=2 cắt dữ liệu thành hai nửa trái và phải thay vì tách hai vành. Giải thích và lựa chọn phù hợp hơn là:","code":"","a":["K-means chỉ tạo các cụm lồi quanh tâm (ranh giới Voronoi); DBSCAN dựa trên mật độ nên tách được hai vành","K-means bị kẹt ở cực tiểu địa phương; chạy lại với nhiều khởi tạo ngẫu nhiên là tách đúng hai vành","Dữ liệu chưa được chuẩn hóa; sau StandardScaler, K-means sẽ tách đúng hai vành tròn","Số cụm K K chưa đủ; tăng K K lên 4 rồi gộp các cụm có tâm gần nhau sẽ tách được hai vành"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":58},{"q":"Câu mệnh đề ( A ∨ B ) → C (A∨B)→C tương đương với dạng chuẩn tắc hội (CNF) nào?","code":"","a":["¬ A ∧ ¬ B ∧ C ¬A∧¬B∧C","( ¬ A ∨ C ) ∧ ( ¬ B ∨ C ) (¬A∨C)∧(¬B∨C)","( A ∨ C ) ∧ ( B ∨ C ) (A∨C)∧(B∨C)","A ∨ B ∨ C A∨B∨C"],"c":1,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":59},{"q":"Trong một head attention, Q = K Q=K và ma trận điểm số là S = Q Q T S=QQ T . Ma trận A A thu được bằng cách áp dụng hàm softmax riêng cho từng hàng của S S. Nhận định nào đúng về tính đối xứng của S S và A A?","code":"","a":["S S không nhất thiết đối xứng; A A đối xứng.","S S và A A đều không nhất thiết đối xứng.","S S và A A đều đối xứng.","S S luôn đối xứng; A A không nhất thiết đối xứng."],"c":3,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":60},{"q":"Đoạn code numpy tính khoảng cách Euclid giữa 1 điểm truy vấn và toàn bộ tập huấn luyện cho k-NN. Với X = [ [ 0 , 0 ] , [ 3 , 4 ] , [ 1 , 1 ] ] X=[[0,0],[3,4],[1,1]] và query = [0,0], mảng dists in ra là gì?","code":"import numpy as np\r\nX = np.array([[0,0],[3,4],[1,1]])\r\nquery = np.array([0,0])\r\ndists = np.sqrt(np.sum((X - query)**2, axis=1))\r\nprint(dists)","a":["[0. 7. 2.]","[0. 25. 2.]","[0. 5. 2.]","[0. 5. 1.41421356]"],"c":3,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":61},{"q":"Dữ liệu 2 chiều đã được trừ trung bình có ma trận hiệp phương sai Σ = [ 3 1 1 3 ] Σ=[ 3 1 ​ 1 3 ​ ]. Thành phần chính thứ nhất giữ lại bao nhiêu phần trăm tổng phương sai?","code":"","a":["75%","50%","80%","Khoảng 66.7%"],"c":3,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":62},{"q":"Sự khác biệt cơ bản giữa phương pháp Temporal Difference (TD, ví dụ Q-learning) và Monte Carlo trong việc ước lượng hàm giá trị là gì?","code":"","a":["Monte Carlo chỉ áp dụng được cho bài toán có không gian hành động liên tục, còn TD chỉ hoạt động với không gian hành động rời rạc hữu hạn","Cả hai đều giống nhau về cách cập nhật giá trị, chỉ khác nhau ở tên gọi lịch sử do hai nhóm nghiên cứu độc lập đặt ra","TD cập nhật giá trị ngay sau mỗi bước dựa trên ước lượng bước kế tiếp (bootstrapping); Monte Carlo phải đợi hết episode mới tính return thực tế để cập nhật","TD phải đợi đến hết episode mới cập nhật giá trị dựa trên return thực tế, còn Monte Carlo cập nhật ngay sau mỗi bước bằng cách bootstrapping từ ước lượng kế tiếp"],"c":2,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":63},{"q":"Ba biến X , Y , Z X,Y,Z đều có miền giá trị {0, 1}, với các ràng buộc nhị phân X ≠ Y , Y ≠ Z X  =Y,Y  =Z và Z ≠ X Z  =X. Áp dụng thuật toán kiểm tra nhất quán cung AC-3 (Arc Consistency Algorithm 3) cho các ràng buộc này đến khi ổn định. Kết quả nào đúng?","code":"","a":["Có miền giá trị bị làm rỗng; thuật toán kết luận ngay bài toán vô nghiệm.","Mỗi miền giá trị còn đúng một giá trị duy nhất; bài toán có nghiệm.","Các miền giá trị giữ nguyên {0, 1}; bài toán thực tế có nghiệm.","Các miền giá trị giữ nguyên {0, 1}; nhưng bài toán thực tế vẫn vô nghiệm."],"c":3,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":64},{"q":"Tập test có 1000 giao dịch thẻ, gồm 950 giao dịch hợp lệ và 50 giao dịch gian lận. Mô hình dự đoán tất cả đều hợp lệ. Cặp giá trị (accuracy; recall của lớp gian lận) là gì?","code":"","a":["(95%; 0%)","(100%; 0%)","(95%; 95%)","(5%; 100%)"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":65},{"q":"Sắp xếp các giai đoạn theo đúng thứ tự của quy trình huấn luyện trợ lý hội thoại kiểu InstructGPT: (1) Tối ưu policy bằng PPO dựa trên điểm của reward model (2) Pre-training với mục tiêu next-token prediction trên kho văn bản lớn (3) Thu thập dữ liệu so sánh: người gán nhãn xếp hạng nhiều phản hồi cho cùng một prompt (4) SFT trên các cặp (chỉ dẫn, phản hồi mẫu) của tập huấn luyện (5) Huấn luyện reward model từ dữ liệu so sánh","code":"","a":["4 → → 2 → → 3 → → 5 → → 1","2 → → 4 → → 3 → → 5 → → 1","2 → → 4 → → 5 → → 3 → → 1","2 → → 4 → → 3 → → 1 → → 5"],"c":1,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":66},{"q":"Xét hai câu: “Con đường này đông xe” và “Cho thêm hai thìa đường vào cà phê”. Gọi v 1 , v 2 v 1 ​ ,v 2 ​ là vector của từ “đường” trong hai câu. Phát biểu nào đúng?","code":"","a":["Với Word2Vec, v 1 ≠ v 2 v 1 ​  =v 2 ​ vì cửa sổ ngữ cảnh khác nhau; với BERT, v 1 = v 2 v 1 ​ =v 2 ​ vì cùng token id","Với Word2Vec, v 1 = v 2 v 1 ​ =v 2 ​ vì mỗi từ có một vector cố định; với BERT, v 1 ≠ v 2 v 1 ​  =v 2 ​ vì vector phụ thuộc ngữ cảnh","Với cả Word2Vec và BERT, v 1 = v 2 v 1 ​ =v 2 ​ vì cả hai đều tra bảng embedding theo token id","Với cả hai mô hình, v 1 ≠ v 2 v 1 ​  =v 2 ​ , nhưng với Word2Vec điều đó chỉ xảy ra khi “đường” là từ OOV"],"c":1,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":67},{"q":"Sắp xếp theo đúng thứ tự các bước xử lý dữ liệu từ đầu vào qua khối encoder ĐẦU TIÊN của Transformer (kiến trúc gốc, Post-LN): (1) Kết nối tắt (residual) cộng với đầu vào rồi Layer Normalization (Add và Norm) (2) Embedding đầu vào cộng với Positional Encoding (3) Multi-Head Self-Attention trên chuỗi đầu vào (4) Kết nối tắt (residual) cộng với đầu ra FFN rồi Layer Normalization (Add và Norm) lần 2 (5) Feed-Forward Network (2 lớp fully-connected với activation ở giữa)","code":"","a":["2 → → 5 → → 1 → → 3 → → 4","3 → → 2 → → 1 → → 5 → → 4","2 → → 3 → → 1 → → 5 → → 4","2 → → 3 → → 5 → → 1 → → 4"],"c":2,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":68},{"q":"Điều kiện nào để một hàm heuristic h ( n ) h(n) được gọi là “admissible” (chấp nhận được) trong thuật toán A*?","code":"","a":["h ( n ) h(n) không bao giờ đánh giá cao hơn (overestimate) chi phí thực tế nhỏ nhất từ n n đến đích, tức h ( n ) ≤ h ∗ ( n ) h(n)≤h ∗ (n) với mọi n n","h ( n ) h(n) phải luôn bằng 0 với mọi trạng thái, tức là không mang bất kỳ thông tin ước lượng nào về khoảng cách còn lại đến đích","h ( n ) h(n) phải là hàm tuyến tính theo số bước còn lại đến đích, không phụ thuộc vào chi phí thực tế của từng cạnh trên đường đi","h ( n ) h(n) phải luôn bằng chi phí thực tế nhỏ nhất từ n n đến đích, tức h ( n ) = h ∗ ( n ) h(n)=h ∗ (n)"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":69},{"q":"So sánh BFS (Breadth-First Search) và DFS (Depth-First Search) về tính đầy đủ (completeness) và tối ưu (optimality) trên đồ thị hữu hạn với chi phí cạnh bằng nhau?","code":"","a":["BFS đầy đủ và tối ưu (khi chi phí cạnh bằng nhau); DFS đầy đủ trên đồ thị hữu hạn (có kiểm tra visited) nhưng KHÔNG đảm bảo tối ưu (có thể tìm ra đường đi dài hơn trước)","Cả hai thuật toán đều đầy đủ và luôn cho ra lời giải tối ưu, không phụ thuộc vào chi phí của từng cạnh nối","Cả hai thuật toán đều trở nên không đầy đủ khi áp dụng lên một đồ thị có số lượng trạng thái là vô hạn, không thể liệt kê hết","DFS luôn cho ra kết quả tốt hơn BFS nhờ chiến lược duyệt theo chiều sâu trước"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":70},{"q":"Đoạn code tokenize một câu tiếng Anh đơn giản bằng split() mặc định. Với câu \"AI is amazing!\", kết quả tokens in ra là gì?","code":"sentence = \"AI is amazing!\"\r\ntokens = sentence.split()\r\nprint(tokens)","a":["['AI', 'is', 'amazing!']","['AI', 'is', 'amazing']","['AI is amazing!']","['A', 'I', 'is', 'amazing', '!']"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":71},{"q":"Sau khi thực hiện một hành động, tác nhân nhận phần thưởng r = 1 r=1 và chuyển đến trạng thái chưa kết thúc s ′ s ′ . Tại s ′ s ′ , hai hành động khả thi có giá trị Q Q lần lượt là 6 và 2; chính sách khám phá đã chọn hành động có Q = 2 Q=2. Với hệ số chiết khấu γ = 0.5 γ=0.5, mục tiêu cập nhật (update target) một bước của Q-learning và SARSA lần lượt là bao nhiêu?","code":"","a":["Q-learning: 2; SARSA: 4.","Q-learning: 4; SARSA: 2.","Q-learning: 4; SARSA: 4.","Q-learning: 3; SARSA: 3."],"c":1,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":72},{"q":"Hàm giá trị hành động tối ưu Q ∗ ( s , a ) Q ∗ (s,a) liên hệ với hàm giá trị trạng thái tối ưu V ∗ ( s ) V ∗ (s) như thế nào?","code":"","a":["V ∗ ( s ) = max ⁡ a Q ∗ ( s , a ) V ∗ (s)=max a ​ Q ∗ (s,a): giá trị tối ưu một trạng thái bằng giá trị Q Q lớn nhất đạt được khi chọn hành động tốt nhất tại trạng thái đó","V ∗ ( s ) V ∗ (s) luôn bằng 0 với mọi s s, bất kể phần thưởng nhận được và chính sách mà agent đang theo đuổi trong suốt quá trình học","Q ∗ ( s , a ) = V ∗ ( s ) Q ∗ (s,a)=V ∗ (s) với mọi hành động a a, vì theo giả định này giá trị trạng thái không phụ thuộc vào hành động được chọn","V ∗ ( s ) = min ⁡ a Q ∗ ( s , a ) V ∗ (s)=min a ​ Q ∗ (s,a), vì theo lập luận này agent tối ưu luôn chọn hành động có giá trị nhỏ nhất để phòng ngừa rủi ro tối đa"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":73},{"q":"Trong LSTM, forget gate f t f t ​ có vai trò gì?","code":"","a":["Quyết định phần nào của cell state sẽ được đưa ra làm hidden state đầu ra","Khởi tạo trọng số ban đầu cho toàn bộ mạng LSTM","Quyết định thông tin mới nào từ đầu vào hiện tại sẽ được thêm vào cell state","Quyết định phần nào của cell state trước đó ( C t − 1 C t−1 ​ ) sẽ được giữ lại hay loại bỏ"],"c":3,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":74},{"q":"","code":"import torch\nimport torch.nn as nn\nx = torch.tensor([[1.0, 3.0],\n[2.0, 2.0]]) # (batch = 2, đặc trưng = 2)\nln = nn.LayerNorm(2, elementwise_affine=False)\nbn = nn.BatchNorm1d(2, affine=False) # đang ở chế độ train\nprint(ln(x).round(decimals=2), bn(x).round(decimals=2))\nKết quả in ra xấp xỉ là:","a":["LN: [[-1, 1], [0, 0]]; BN: [[-1, 1], [1, -1]]","LN: [[-1, 1], [1, -1]]; BN: [[-1, 1], [0, 0]]","Cả LN và BN đều cho [[-1, 1], [0, 0]]","LN: [[-1, 1], [0, 0]]; BN: [[-1, -1], [1, 1]]"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":75},{"q":"Đoạn code dưới đây cài đặt “inverted dropout” cho tầng ẩn với xác suất giữ lại keep_prob lúc huấn luyện, nhưng thiếu một bước để giá trị kỳ vọng đầu ra không đổi so với lúc không dùng dropout. Cần bổ sung gì?","code":"import numpy as np\r\ndef dropout_forward(a, keep_prob):\r\n    mask = (np.random.rand(*a.shape) < keep_prob)\r\n    a = a * mask\r\n    return a","a":["Cần nhân thêm mask một lần nữa lên toàn bộ đầu ra ngay sau bước nhân đầu tiên để tăng cường mức độ regularization của cả mạng","Cần đổi hàm np.random.rand thành np.random.randn để tạo ra mask ngẫu nhiên theo phân phối chuẩn thay vì phân phối đều trong [0,1]","Không cần bổ sung, đoạn code hiện tại đã cài đặt đúng kỹ thuật inverted dropout theo lý thuyết","Cần chia a cho keep_prob sau khi nhân mask (a = a * mask / keep_prob) để giữ kỳ vọng đầu ra không đổi (inverted dropout), tránh phải scale lại lúc inference"],"c":3,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":76},{"q":"Sắp xếp các bước theo đúng thứ tự của Value Iteration để tìm hàm giá trị tối ưu V ∗ ( s ) V ∗ (s) cho một MDP đã biết đầy đủ mô hình ( P , R ) (P,R): (1) Lặp lại việc cập nhật cho toàn bộ trạng thái nhiều vòng cho đến khi V ( s ) V(s) thay đổi dưới một ngưỡng ϵ ϵ (hội tụ) (2) Suy ra chính sách tối ưu π ∗ ( s ) = arg ⁡ max ⁡ a ∑ s ′ P ( s ′ ∣ s , a ) [ R ( s , a , s ′ ) + γ V ( s ′ ) ] π ∗ (s)=argmax a ​ ∑ s ′ ​ P(s ′ ∣s,a)[R(s,a,s ′ )+γV(s ′ )] từ V ∗ V ∗ đã hội tụ (3) Với mỗi trạng thái s s, cập nhật V ( s ) ← max ⁡ a ∑ s ′ P ( s ′ ∣ s , a ) [ R ( s , a , s ′ ) + γ V ( s ′ ) ] V(s)←max a ​ ∑ s ′ ​ P(s ′ ∣s,a)[R(s,a,s ′ )+γV(s ′ )] (4) Khởi tạo V ( s ) = 0 V(s)=0 (hoặc giá trị tuỳ ý) cho mọi trạng thái s s","code":"","a":["4 → → 2 → → 3 → → 1","4 → → 3 → → 1 → → 2","3 → → 4 → → 1 → → 2","4 → → 3 → → 2 → → 1"],"c":1,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":77},{"q":"Sắp xếp các bước theo đúng thứ tự để huấn luyện một Autoencoder cơ bản nhằm nén và tái tạo dữ liệu: (1) Đưa dữ liệu đầu vào x x qua encoder để thu được biểu diễn ẩn (latent) z z có số chiều nhỏ hơn x x (2) Đưa z z qua decoder để tái tạo lại x ^ x ^ có cùng kích thước với x x (3) Lan truyền ngược và cập nhật trọng số của cả encoder và decoder để giảm reconstruction loss (4) Tính hàm mất mát tái tạo (reconstruction loss), ví dụ MSE giữa x x và x ^ x ^","code":"","a":["1 → → 4 → → 2 → → 3","2 → → 1 → → 4 → → 3","1 → → 2 → → 3 → → 4","1 → → 2 → → 4 → → 3"],"c":3,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":78},{"q":"Dự báo doanh số theo ngày với dữ liệu 3 năm. Nhóm dùng KFold(n_splits=5, shuffle=True) để chọn mô hình và đạt sai số thấp, nhưng khi triển khai sai số tăng gấp ba. Nguyên nhân và cách sửa hợp lý nhất là:","code":"","a":["Số fold chưa đủ; tăng lên 10 fold để ước lượng sai số ổn định hơn","Xáo trộn cho phép dùng dữ liệu tương lai để dự báo quá khứ; cần chia theo thời gian (TimeSeriesSplit)","Dữ liệu chưa được chuẩn hóa; cần thêm StandardScaler vào trước mô hình","Mô hình bị underfitting; cần tăng độ phức tạp để giảm sai số khi triển khai"],"c":1,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":79},{"q":"Đoạn code tính MSE và MAE cho 3 cặp (y_true, y_pred) = (3, 2.5), (5, 5.5), (2, 4). Kết quả in ra (làm tròn 2 chữ số) là gì?","code":"import numpy as np\r\ny_true = np.array([3, 5, 2])\r\ny_pred = np.array([2.5, 5.5, 4])\r\nmse = np.mean((y_true - y_pred)**2)\r\nmae = np.mean(np.abs(y_true - y_pred))\r\nprint(round(mse, 2), round(mae, 2))","a":["1.83 0.83","0.83 1.83","1.5 1.0","1.83 1.5"],"c":2,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":80},{"q":"K-means++ cải tiến K-means thông thường ở điểm nào?","code":"","a":["Thay khoảng cách Euclid bằng khoảng cách cosine khi tính khoảng cách giữa các điểm và tâm cụm","Chuyển bài toán phân cụm không giám sát thành một bài toán phân loại có giám sát với nhãn được gán trước","Khởi tạo tâm cụm ban đầu theo xác suất tỉ lệ với bình phương khoảng cách đến tâm gần nhất đã chọn, giảm nguy cơ hội tụ về nghiệm cục bộ kém","Tự động xác định và chọn ra số cụm K K tối ưu mà không cần người dùng chỉ định trước giá trị này"],"c":2,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":81},{"q":"Sắp xếp các bước theo đúng thứ tự trong MỘT bước lặp của thuật toán Q-learning: (1) Thực hiện hành động a a, nhận phần thưởng r r và trạng thái kế tiếp s ′ s ′ (2) Chuyển sang trạng thái mới: s ← s ′ s←s ′ (3) Cập nhật Q ( s , a ) Q(s,a) theo công thức Q ( s , a ) ← Q ( s , a ) + α [ r + γ max ⁡ a ′ Q ( s ′ , a ′ ) − Q ( s , a ) ] Q(s,a)←Q(s,a)+α[r+γmax a ′ ​ Q(s ′ ,a ′ )−Q(s,a)] (4) Quan sát trạng thái hiện tại s s (5) Chọn hành động a a theo chiến lược epsilon-greedy dựa trên Q ( s , ⋅ ) Q(s,⋅)","code":"","a":["4 → → 1 → → 5 → → 3 → → 2","4 → → 5 → → 3 → → 1 → → 2","5 → → 4 → → 1 → → 3 → → 2","4 → → 5 → → 1 → → 3 → → 2"],"c":3,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":82},{"q":"Huấn luyện BPE trên một kho từ (ban đầu tách thành từng ký tự) với tần suất: hug × 10 ×10, pug × 5 ×5, pun × 12 ×12, bun × 4 ×4, hugs × 5 ×5. Phép gộp (merge) đầu tiên được chọn là:","code":"","a":["p + u → → pu","u + n → → un","h + u → → hu","u + g → → ug"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":83},{"q":"Sắp xếp các bước theo đúng thứ tự của thuật toán AdaBoost (từ khởi tạo đến hết vòng lặp đầu tiên): (1) Khởi tạo trọng số bằng nhau cho mọi mẫu huấn luyện (2) Huấn luyện một bộ học yếu trên dữ liệu có trọng số hiện tại (3) Tính trọng số của bộ học yếu (alpha) dựa trên sai số có trọng số của nó (4) Tính sai số có trọng số (weighted error) của bộ học yếu vừa huấn luyện (5) Cập nhật và chuẩn hoá lại trọng số các mẫu (tăng trọng số mẫu sai, giảm trọng số mẫu đúng)","code":"","a":["1 → → 2 → → 4 → → 3 → → 5","1 → → 2 → → 3 → → 4 → → 5","2 → → 1 → → 4 → → 3 → → 5","1 → → 2 → → 4 → → 5 → → 3"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":84},{"q":"Sắp xếp các bước theo đúng thứ tự của một khối “bottleneck” trong ResNet-50 (khác với basic block 2 lớp 3 × 3 3×3 của ResNet-18/34, đây là dạng 3 lớp 1 × 1 – 3 × 3 – 1 × 1 1×1–3×3–1×1 có kết nối tắt): (1) Conv 3 × 3 3×3 xử lý đặc trưng không gian, theo sau bởi BatchNorm và ReLU (2) Cộng X_shortcut vào kết quả nhánh chính (Add), sau đó mới áp dụng ReLU cuối cùng (3) Lưu lại đầu vào X làm X_shortcut để dùng cho kết nối tắt sau này (4) Conv 1 × 1 1×1 giảm số kênh (bottleneck), theo sau bởi BatchNorm và ReLU (5) Conv 1 × 1 1×1 khôi phục lại số kênh ban đầu, theo sau bởi BatchNorm (chưa ReLU)","code":"","a":["4 → → 1 → → 5 → → 3 → → 2","3 → → 4 → → 1 → → 5 → → 2","3 → → 1 → → 4 → → 5 → → 2","3 → → 4 → → 1 → → 2 → → 5"],"c":1,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":85},{"q":"Trong mô hình YOLOv1, mỗi ô lưới (grid cell) dự đoán B B hộp giới hạn (bounding box). Giả sử hai vật thể thuộc hai lớp khác nhau có tâm nằm trong cùng một ô lưới. Thành phần nào trong dự đoán của ô lưới không thể được biểu diễn độc lập cho từng hộp?","code":"","a":["Phân bố xác suất lớp (class probability distribution).","Điểm tin cậy (confidence score) của từng hộp.","Chiều rộng và chiều cao ( w , h ) (w,h) của từng hộp.","Tọa độ tâm ( x , y ) (x,y) của từng hộp."],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":86},{"q":"","code":"x = [2.0, -3.0, 4.0]\nw_h, h = 0.5, 0.0\nfor x_t in x:\nh = max(0.0, w_h * h + x_t) # RNN đơn giản với ReLU, trọng số đầu vào = 1\nprint(h)\nKết quả in ra là:","a":["3.0","5.0","6.0","4.0"],"c":3,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":87},{"q":"Mô hình CNN dưới đây báo lỗi “shape mismatch” (RuntimeError) tại lớp Linear khi forward ảnh 32 × 32 × 3 32×32×3 sau 2 lớp Conv+Pool. Lỗi nhiều khả năng nhất do đâu?","code":"import torch\r\nimport torch.nn as nn\nclass SimpleCNN(nn.Module):\r\n    def __init__(self):\r\n        super().__init__()\r\n        self.conv1 = nn.Conv2d(3, 8, 3, padding=1)\r\n        self.pool = nn.MaxPool2d(2, 2)\r\n        self.conv2 = nn.Conv2d(8, 16, 3, padding=1)\r\n        self.fc = nn.Linear(16 * 32 * 32, 10)\ndef forward(self, x):\r\n        x = self.pool(torch.relu(self.conv1(x)))\r\n        x = self.pool(torch.relu(self.conv2(x)))\r\n        x = x.view(x.size(0), -1)\r\n        return self.fc(x)","a":["Cú pháp x.view(x.size(0), -1) sai về mặt cú pháp Python, phải thay bằng x.reshape() thì mới chạy được","nn.Linear được khởi tạo với kích thước đầu vào sai: sau 2 lần MaxPool2d(2,2), ảnh 32 × 32 32×32 co lại còn 8 × 8 8×8, nên phải là nn.Linear(16*8*8, 10) thay vì 16*32*32","Lớp MaxPool2d(2,2) không tồn tại trong thư viện PyTorch","Lớp Conv2d không được phép dùng tham số padding=1 khi huấn luyện mạng CNN"],"c":1,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":88},{"q":"Sắp xếp các bước theo đúng thứ tự khi Minimax (không cắt tỉa) tính giá trị cho một cây trò chơi có các tầng Max (gốc) – Min – Max – Min, với các nút lá nằm ngay dưới tầng Min cuối cùng, bắt đầu từ việc tính giá trị các nút lá: (1) Lan truyền tiếp lên gốc (nếu còn tầng), lặp lại việc lấy max/min tuỳ theo lượt chơi của tầng đó (2) Tại các nút Min ở tầng ngay trên lá, lấy giá trị nhỏ nhất trong các nút con (3) Tính giá trị (điểm số) tại các nút lá bằng hàm đánh giá (evaluation function) hoặc kết quả trận đấu thực tế (4) Chọn nước đi tại gốc tương ứng với nhánh con có giá trị bằng giá trị tối ưu vừa tính được ở gốc (5) Tại các nút Max ở tầng tiếp theo, lấy giá trị lớn nhất trong các nút con (là các nút Min vừa tính)","code":"","a":["3 → → 5 → → 2 → → 1 → → 4","2 → → 3 → → 5 → → 1 → → 4","3 → → 2 → → 5 → → 1 → → 4","3 → → 2 → → 5 → → 4 → → 1"],"c":2,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":89},{"q":"Hệ thống phải vẽ mask riêng cho từng con bò trong ảnh, kể cả khi nhiều con bò cùng lớp đứng sát nhau. Bài toán nào phù hợp nhất?","code":"","a":["Semantic segmentation chỉ có nhãn lớp cho từng pixel","Image classification một nhãn","Instance segmentation","Image retrieval"],"c":2,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":90},{"q":"Sắp xếp các bước theo đúng thứ tự của giải thuật Backtracking Search kết hợp Forward Checking cho CSP: (1) Nếu forward checking khiến domain của biến láng giềng nào đó rỗng, quay lui (backtrack) và thử giá trị khác (2) Chọn một biến chưa được gán giá trị (theo một thứ tự/heuristic nào đó) (3) Nếu không có domain nào rỗng, lặp lại quá trình với biến chưa gán kế tiếp; khi mọi biến đã được gán hợp lệ thì trả về phép gán làm nghiệm của CSP (4) Với mỗi giá trị thử, kiểm tra tính hợp lệ với các ràng buộc đã có, rồi áp dụng forward checking để loại giá trị không tương thích khỏi domain của các biến láng giềng chưa gán (5) Thử lần lượt từng giá trị trong domain hiện tại của biến đó","code":"","a":["5 → → 2 → → 4 → → 1 → → 3","2 → → 5 → → 4 → → 1 → → 3","2 → → 4 → → 5 → → 1 → → 3","2 → → 5 → → 1 → → 4 → → 3"],"c":1,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":91},{"q":"Đoạn code dưới đây huấn luyện SVM kernel RBF trên dữ liệu có 2 đặc trưng với thang đo khác nhau (feature 1: 0-1, feature 2: 0-10000) nhưng độ chính xác thấp. Nguyên nhân nhiều khả năng nhất là gì?","code":"from sklearn.svm import SVC\r\nfrom sklearn.model_selection import train_test_split\nX_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.2)\r\nmodel = SVC(kernel='rbf', C=1.0, gamma='scale')\r\nmodel.fit(X_train, y_train)\r\nprint(model.score(X_test, y_test))","a":["Thiếu bước chuẩn hoá đặc trưng (StandardScaler); khoảng cách trong kernel RBF bị chi phối bởi đặc trưng có thang đo lớn","SVC trong thư viện scikit-learn không hỗ trợ kernel RBF khi dữ liệu chỉ có 2 chiều đặc trưng","Giá trị test_size=0.2 nhỏ nên không đủ dữ liệu để đánh giá mô hình trên tập test","Tham số gamma='scale' chỉ dùng được khi kernel là tuyến tính, không dùng được với kernel RBF"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":92},{"q":"So sánh chi phí bộ nhớ giữa BFS và DFS khi tìm kiếm trên cây có hệ số nhánh b b và độ sâu lời giải d d (hoặc giới hạn độ sâu m m cho DFS)?","code":"","a":["Cả hai đều tốn bộ nhớ như nhau O ( b d ) O(b d ), vì cả hai đều phải lưu lại toàn bộ các nút đã từng được sinh ra trong quá trình tìm kiếm","BFS không cần bộ nhớ vì duyệt tuần tự từng nút một, không giữ lại bất kỳ thông tin nào về các nút đã mở rộng trước đó","DFS luôn tốn nhiều bộ nhớ hơn BFS, vì phải lưu lại toàn bộ cây con đã duyệt qua trước khi quay lui","BFS tốn O ( b d ) O(b d ) vì phải lưu lại toàn bộ biên (frontier) của tầng đang duyệt; DFS chỉ tốn O ( b m ) O(bm) vì chỉ lưu đường đi hiện tại từ gốc cùng các nút anh em chưa mở rộng dọc đường đi đó"],"c":3,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":93},{"q":"Một mô hình Seq2Seq được huấn luyện chỉ bằng teacher forcing đạt loss thấp, nhưng khi sinh câu dài thì một lỗi ở các token đầu kéo theo chuỗi lỗi phía sau. Hiện tượng và biện pháp phù hợp là:","code":"","a":["Exposure bias: khi suy luận, mô hình nhận chính dự đoán của nó thay vì token đúng; dùng scheduled sampling","Vanishing gradient: gradient không truyền tới các bước đầu; thay RNN bằng LSTM","Overfitting: mô hình ghi nhớ tập huấn luyện; tăng dropout và weight decay","Hệ số label smoothing lớn: mô hình thiếu tự tin; giảm hệ số label smoothing về 0"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":94},{"q":"Một LLM decoder-only có 32 lớp, 32 head cho Query nhưng dùng Grouped-Query Attention với 8 head cho Key/Value, head_dim = 128. Suy luận với batch = 1, ngữ cảnh 4096 token, KV cache lưu ở FP16 (2 byte mỗi giá trị). Dung lượng KV cache là bao nhiêu?","code":"","a":["2 GiB","256 MiB","512 MiB","1 GiB"],"c":2,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":95},{"q":"Trong MDP, chính sách (policy) π π được định nghĩa là gì?","code":"","a":["Hàm ánh xạ từ trạng thái sang hành động (tất định) hoặc sang phân phối xác suất trên các hành động (ngẫu nhiên) — quy tắc mà agent dùng để chọn hành động tại mỗi trạng thái","Hàm mất mát dùng để huấn luyện mạng nơ-ron xấp xỉ giá trị, được tối thiểu hoá bằng gradient descent qua mỗi bước cập nhật","Ma trận xác suất chuyển trạng thái của môi trường, mô tả xác suất chuyển từ trạng thái này sang trạng thái khác khi thực hiện một hành động","Tập hợp toàn bộ phần thưởng nhận được trong một episode, được cộng dồn lại để tính tổng return cuối cùng của agent"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":96},{"q":"Một bài toán thoả mãn ràng buộc (Constraint Satisfaction Problem - CSP) được định nghĩa bởi các thành phần nào?","code":"","a":["Tập biến (variables), miền giá trị của mỗi biến (domains), và tập các ràng buộc (constraints) giữa các biến","Chỉ bao gồm tập trạng thái và một hàm phần thưởng, giống như trong bài toán RL","Chỉ bao gồm một hàm mục tiêu (objective function) cần được tối ưu hoá trong quá trình tìm kiếm","Chỉ bao gồm tập biến (variables) và miền giá trị (domains), không cần định nghĩa thêm ràng buộc nào khác"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":97},{"q":"Đoạn code sau tính perplexity của một mô hình ngôn ngữ trên chuỗi 4 token.","code":"import math\r\nprobs = [0.5, 0.25, 0.25, 0.125] # xác suất mô hình gán cho token đúng ở mỗi vị trí\r\nnll = [-math.log2(p) for p in probs]\r\navg = sum(nll) / len(nll)\r\nprint(avg, 2 ** avg)\nKết quả in ra là:","a":["2.0 4.0","8.0 256.0","2.0 0.25","1.386 2.614"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":98},{"q":"Áp dụng Non-Maximum Suppression (NMS) với ngưỡng IoU = 0.5 cho 3 hộp cùng lớp, đã sắp xếp theo confidence giảm dần: Box1 (conf cao nhất), Box2 (IoU với Box1 = 0.7), Box3 (IoU với Box1 = 0.3, IoU với Box2 = 0.2). Theo đoạn code NMS chuẩn dưới đây, những hộp nào được giữ lại?","code":"def nms(boxes_sorted_by_conf, iou_fn, threshold=0.5):\r\n    keep = []\r\n    remaining = boxes_sorted_by_conf[:]\r\n    while remaining:\r\n        current = remaining.pop(0)\r\n        keep.append(current)\r\n        remaining = [b for b in remaining if iou_fn(current, b) < threshold]\r\n    return keep","a":["Giữ Box1 và Box3","Giữ cả 3 Box1, Box2, Box3","Chỉ giữ Box1","Giữ Box1 và Box2"],"c":0,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":99},{"q":"Sắp xếp các bước theo đúng thứ tự trong pipeline phát hiện đối tượng của YOLO (You Only Look Once) phiên bản cơ bản: (1) Chia ảnh đầu vào thành lưới ô vuông (grid) S × S S×S (2) Lọc bỏ các hộp có điểm tin cậy thấp hơn ngưỡng đặt trước (3) Áp dụng Non-Maximum Suppression (NMS) để loại các hộp trùng lặp cho cùng một đối tượng (4) Mỗi ô lưới dự đoán đồng thời các hộp giới hạn (bounding box), điểm tin cậy (confidence) và xác suất lớp trong một lượt truyền tiến (forward pass) duy nhất qua mạng CNN (5) Xuất ra danh sách các hộp giới hạn cuối cùng cùng nhãn lớp tương ứng","code":"","a":["4 → → 1 → → 2 → → 3 → → 5","1 → → 4 → → 2 → → 3 → → 5","1 → → 2 → → 4 → → 3 → → 5","1 → → 4 → → 2 → → 5 → → 3"],"c":1,"e":"Đáp án tham khảo do mình suy luận từ nội dung câu hỏi; file nguồn không đánh dấu đáp án.","sourceNumber":100}];